// an inverted gaussian function, 
// where f(0) = 0. 
// Graph: https://www.desmos.com/calculator/torawryxnq
float inv_g(float x) {
  return -1./pow(2., (0.6*pow(x, 2.)))+1.;
}

float interact(float x, float y, float z) {
  float f = 0.012;
  return x + ((z - x) - (x - y)) * f;
}

vec3 activation(float r, float g, float b) {
  float i_r = interact(r, g, b);
  float i_g = interact(g, b, r);
  float i_b = interact(b, r, g);
  r = inv_g(i_r);
  g = inv_g(i_g);
  b = inv_g(i_b);
  return vec3(r, g, b);
}
